public class Solution {
    // Invariante: tudo em [0, lo) é < x e tudo em [hi, n) é >= x.
    static int lowerBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] <= x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int[] faixa(int[] a, int x) {
        int l = lowerBound(a, x);
        if (l == a.length || a[l] != x) return new int[]{-1, -1};
        return new int[]{l, upperBound(a, x) - 1};
    }
}

