import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static final int[] A = {1, 2, 2, 2, 5, 7};

    @Test void lower() {
        assertEquals(1, Solution.lowerBound(A, 2));
        assertEquals(4, Solution.lowerBound(A, 3));
        assertEquals(0, Solution.lowerBound(A, -9));
        assertEquals(6, Solution.lowerBound(A, 99));
    }

    @Test void upper() {
        assertEquals(4, Solution.upperBound(A, 2));
        assertEquals(6, Solution.upperBound(A, 7));
        assertEquals(0, Solution.upperBound(A, 0));
    }

    @Test void faixa() {
        assertArrayEquals(new int[]{1, 3}, Solution.faixa(A, 2));
        assertArrayEquals(new int[]{5, 5}, Solution.faixa(A, 7));
        assertArrayEquals(new int[]{-1, -1}, Solution.faixa(A, 3));
        assertArrayEquals(new int[]{-1, -1}, Solution.faixa(new int[]{}, 3));
    }

    @Test void grandeComExtremos() {
        int[] a = new int[1 << 20];
        java.util.Arrays.fill(a, Integer.MAX_VALUE);
        assertEquals(0, Solution.lowerBound(a, Integer.MAX_VALUE));
        assertEquals(a.length, Solution.upperBound(a, Integer.MAX_VALUE));
    }
}

