import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        int[] a = {4, 5, 6, 7, 0, 1, 2};
        assertEquals(4, Solution.buscar(a, 0));
        assertEquals(0, Solution.buscar(a, 4));
        assertEquals(6, Solution.buscar(a, 2));
        assertEquals(-1, Solution.buscar(a, 3));
    }

    @Test void semRotacaoEPequenos() {
        assertEquals(2, Solution.buscar(new int[]{1, 2, 3, 4}, 3));
        assertEquals(-1, Solution.buscar(new int[]{}, 1));
        assertEquals(1, Solution.buscar(new int[]{3, 1}, 1));
    }

    @Test void todasAsRotacoes() {
        int n = 50;
        for (int r = 0; r < n; r++) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = ((i + r) % n) * 2;
            for (int i = 0; i < n; i++) assertEquals(i, Solution.buscar(a, a[i]), "rotação " + r);
            assertEquals(-1, Solution.buscar(a, 7));
        }
    }
}
